import React, { createContext, useState, useEffect } from 'react';
import { ethers } from 'ethers';
import { SepoliaConfig } from '../config/chainConfig';

export const Web3Context = createContext();

export const Web3Provider = ({ children }) => {
  const [currentAccount, setCurrentAccount] = useState("");

  const connectWallet = async () => {
    if (!window.ethereum) return alert("Cài Metamask đi bạn!");

    try {
      // 1. Yêu cầu chuyển mạng sang Sepolia
      await window.ethereum.request({
        method: 'wallet_switchEthereumChain',
        params: [{ chainId: SepoliaConfig.chainId }],
      });
    } catch (switchError) {
      // Nếu chưa có mạng thì thêm vào
      if (switchError.code === 4902) {
        await window.ethereum.request({
          method: 'wallet_addEthereumChain',
          params: [SepoliaConfig],
        });
      }
    }

    // 2. Lấy tài khoản
    const provider = new ethers.BrowserProvider(window.ethereum);
    const accounts = await provider.send("eth_requestAccounts", []);
    setCurrentAccount(accounts[0]);
  };

  return (
    <Web3Context.Provider value={{ currentAccount, connectWallet }}>
      {children}
    </Web3Context.Provider>
  );
};
